# Lesson 2 - parts 5, 6 (GCD, LCM), 7 (exercises), summary and the closing slide
import sys, os, json
sys.path.insert(0, os.path.dirname(__file__))
from vis2 import *
from lib import stepify

K5, K6, KX = '5. តួចែករួមធំបំផុត (GCD)', '6. ពហុគុណរួមតូចបំផុត (LCM)', 'លំហាត់'


def build():
    S = []
    # ------------------------------------------------------------ 5  GCD
    hook = fig(svg(1000, 150, '<circle cx="410" cy="75" r="62" fill="%s" fill-opacity=".2" stroke="%s" stroke-width="5"/><circle cx="590" cy="75" r="62" fill="%s" fill-opacity=".2" stroke="%s" stroke-width="5"/>' % (BLUE, BLUE, ORANGE, ORANGE) + T(500, 92, '6', 56, RED) + T(330, 90, '30', 34, BLUE) + T(670, 90, '36', 34, ORANGE), '19vh'), 'តួចែកដែលនៅក្នុងទាំងពីរ · ធំជាងគេ')
    S.append(part(5, 'តួចែករួមធំបំផុត (GCD)', hook))
    d30, d36 = [1, 2, 3, 5, 6, 10, 15, 30], [1, 2, 3, 4, 6, 9, 12, 18, 36]
    S.append(ex(K5, 'ឧទាហរណ៍ 1', p('រកតួចែករួមធំបំផុតនៃ ' + m('30') + ' និង ' + m('36') + ' ។') + fig(venn(d30, d36, [1, 2, 3, 6], 'តួចែកនៃ 30', 'តួចែកនៃ 36', 6)) + rvd(1, p('តួចែករួមនៃ ' + m('30') + ' និង ' + m('36') + ' គឺ ' + m('1, 2, 3') + ' និង ' + m('6') + ' ។')) + rvd(3, p('តួចែករួមធំបំផុតគឺ ' + hl(m('6'), RED) + ' ។ គេសរសេរ ' + hl(m('GCD(30,36)=6'), RED) + ' ។'))))
    S.append(ex(K5, 'ឧទាហរណ៍ 1 · វិធីម្យ៉ាងទៀត', p('បំបែក ' + m('30') + ' និង ' + m('36') + ' ជាផលគុណកត្តាបឋម ៖') + dm('\\begin{aligned}30&=\\boxed{2}\\times\\boxed{3}\\times 5\\\\ 36&=\\boxed{2^{2}}\\times\\boxed{3^{2}}\\end{aligned}')
                    + rvd(1, p('កត្តារួមដែលមាននិទស្សន្ត ' + hl('តូចជាងគេ', RED) + ' គឺ ' + m('2') + ' និង ' + m('3'))) + rvd(2, p('ដូច្នេះ ' + hl(m('GCD(30,36)=2\\times 3=6'), RED) + ' ។'))))
    S.append(ex(K5, 'ឧទាហរណ៍ 2', p('រកតួចែករួមធំបំផុតនៃ ' + m('60, 180') + ' និង ' + m('210') + ' ។') + dm('\\begin{aligned}60&=2^{2}\\times 3\\times 5\\\\ 180&=2^{2}\\times 3^{2}\\times 5\\\\ 210&=2\\times 3\\times 5\\times 7\\end{aligned}') + rvd(1, p('កត្តារួមដែលមាននិទស្សន្តតូចជាងគេគឺ ' + m('2\\times 3\\times 5'))) + rvd(2, p('ដូច្នេះ ' + hl(m('GCD(60,180,210)=2\\times 3\\times 5=30'), RED) + ' ។'))))
    S.append(key(K5, 'ជាទូទៅ', p('ដើម្បីរកតួចែករួមធំបំផុតនៃពីរ ឬច្រើនចំនួន គេបំបែកចំនួននីមួយៗជាផលគុណកត្តាបឋម រួចគេគុណកត្តារួមទាំងអស់ដែលមាននិទស្សន្តតូចជាងគេ ។')))
    S.append(key(K5, 'សម្គាល់', p('ពីរចំនួនជា ' + hl('ចំនួនបឋមរវាងគ្នា', RED) + ' កាលណា GCD របស់វាស្មើនឹង ' + m('1') + ' ។') + p(hl('ឧទាហរណ៍ 3 ៖', NAVY) + ' ចំនួន ' + m('11') + ' និង ' + m('13') + ' ជាចំនួនបឋមរវាងគ្នា ព្រោះ ' + m('GCD(11,13)=1') + ' ។')))
    S.append(prac(K5, 'លំហាត់គំរូ', p('គេចង់ក្រាលឥដ្ឋការ៉ូរាងការ៉េមានទំហំប៉ុនៗគ្នាឱ្យពេញលើផ្ទៃនៃបន្ទប់ទឹកមួយរាងចតុកោណកែងដែលមានទទឹងប្រវែង ' + m('90\\text{ cm}') + ' និងបណ្តោយប្រវែង ' + m('126\\text{ cm}') + ' ។ បញ្ជាក់ប្រវែងជ្រុងនៃឥដ្ឋការ៉ូធំបំផុតដែលអាចប្រើបាន និងចំនួនឥដ្ឋការ៉ូដែលត្រូវប្រើ ។') + fig(tiles_gcd(maxh='26vh'), '')))
    S.append(sol(K5, 'ដំណោះស្រាយ', cols(p('ប្រវែងជ្រុងនៃការ៉ូមួយជាតួចែករួមនៃ ' + m('90') + ' និង ' + m('126') + ' ។ ដើម្បីឱ្យការ៉ូធំបំផុត គេរក GCD ។') + dm('\\begin{cases}90=2\\times 3^{2}\\times 5\\\\ 126=2\\times 3^{2}\\times 7\\end{cases}') + p('គេបាន ' + m('GCD(90,126)=2\\times 3^{2}=18') + ' ។'), fig(tiles_gcd(maxh='34vh'))) + p('ដូច្នេះឥដ្ឋការ៉ូមានជ្រុងប្រវែង ' + hl(m('18\\text{ cm}'), RED) + ' ហើយចំនួនការ៉ូ ' + hl(m('5\\times 7=35'), RED) + ' ។')))
    S.append(prac(K5, 'ប្រតិបត្តិ', p('គេចែកសៀវភៅ ' + m('24') + ' ក្បាលនិងខ្មៅដៃ ' + m('36') + ' ដើមឱ្យសិស្សស្មើៗគ្នាដោយគ្មានឱ្យសល់សៀវភៅឬខ្មៅដៃ ។ គេសម្រេចចិត្តចែកសៀវភៅនិងខ្មៅដៃឱ្យសិស្សបានចំនួនច្រើននាក់បំផុត ។ តើគេអាចចែកឱ្យសិស្សបានប៉ុន្មាននាក់ ហើយសិស្សម្នាក់ៗទទួលបានអ្វីខ្លះ?')))
    S.append(sol(K5, 'ចម្លើយ', p('តាង ' + m('n') + ' ជាចំនួនសិស្សច្រើននាក់បំផុតដែលអាចចែកឱ្យបាន ។ ' + m('n') + ' ត្រូវតែជាតួចែករួមនៃ ' + m('24') + ' និង ' + m('36') + ' ហើយដោយចង់បានច្រើនបំផុត នោះ ' + m('n=GCD(24,36)') + ' ។') + dm('\\begin{aligned}24&=2^{3}\\times 3\\\\ 36&=2^{2}\\times 3^{2}\\end{aligned}') + p('កត្តារួមដែលមាននិទស្សន្តតូចជាងគេគឺ ' + m('2^{2}') + ' និង ' + m('3') + ' ៖') + dm('GCD(24,36)=2^{2}\\times 3=4\\times 3=12') + p('ដូចនេះ គេអាចចែកបានសិស្ស ' + hl('12', RED) + ' នាក់ (ម្នាក់ៗទទួលបានសៀវភៅ ' + hl(m('2'), RED) + ' ក្បាល និងខ្មៅដៃ ' + hl(m('3'), RED) + ' ដើម) ។')))

    # ------------------------------------------------------------ 6  LCM
    hook = fig(svg(1000, 130, ''.join(circ(60 + k * 118, 45, 24, BLUE if k % 6 == 0 or True else BLUE, '#fff', 3) for k in range(0)) + T(500, 80, '6, 12, 18, 24 …', 40, BLUE) + T(500, 124, '8, 16, 24 …  →  ពហុគុណរួមតូចបំផុត = 24', 34, RED), '16vh'), 'ពហុគុណរួម · តូចជាងគេ')
    S.append(part(6, 'ពហុគុណរួមតូចបំផុត (LCM)', hook))
    S.append(ex(K6, 'ឧទាហរណ៍ 1', p('រកពហុគុណរួមតូចបំផុតនៃ ' + m('6') + ' និង ' + m('8') + ' ។') + fig(mult_strip(6, 8, 48), 'ពហុគុណរួមខាងមុខគេ គឺ 24 · 48 …') + rvd(3, p('ពហុគុណរួមតូចបំផុតគឺ ' + hl(m('24'), RED) + ' ។ គេសរសេរ ' + hl(m('LCM(6,8)=24'), RED) + ' ។'))))
    S.append(ex(K6, 'ឧទាហរណ៍ 1 · វិធីម្យ៉ាងទៀត', dm('\\begin{aligned}6&=2\\times 3\\\\ 8&=2^{3}\\end{aligned}') + rvd(1, p('យកកត្តារួមដែលមាននិទស្សន្ត ' + hl('ធំជាងគេ', RED) + ' និងកត្តាមិនរួម ៖ ' + m('2^{3}') + ' និង ' + m('3'))) + rvd(2, p('ដូច្នេះ ' + hl(m('LCM(6,8)=2^{3}\\times 3=24'), RED) + ' ។'))))
    S.append(ex(K6, 'ឧទាហរណ៍ 2', p('រកពហុគុណរួមតូចបំផុតនៃ ' + m('18, 24') + ' និង ' + m('36') + ' ។') + dm('\\begin{aligned}18&=2\\times 3^{2}\\\\ 24&=2^{3}\\times 3\\\\ 36&=2^{2}\\times 3^{2}\\end{aligned}') + rvd(1, p('ដូច្នេះ ' + hl(m('LCM(18,24,36)=2^{3}\\times 3^{2}=8\\times 9=72'), RED) + ' ។'))))
    S.append(key(K6, 'ជាទូទៅ', p('ដើម្បីរកពហុគុណរួមតូចបំផុតនៃពីរ ឬច្រើនចំនួនគេត្រូវបំបែកចំនួននីមួយៗជាផលគុណកត្តាបឋម រួចគេគុណកត្តារួមដែលមាននិទស្សន្តធំជាងគេជាមួយនិងកត្តាមិនរួម ដែលមាននៅក្នុងចំនួនទាំងនោះ ។')))
    S.append(slide(K6, 'ទំនាក់ទំនង GCD និង LCM', p('សម្រាប់ពីរចំនួន ' + m('a') + ' និង ' + m('b') + ' ៖') + dm('GCD(a,b)\\times LCM(a,b)=a\\times b') + rvd(1, p('ឧទាហរណ៍ ' + m('6') + ' និង ' + m('8') + ' ៖ ' + m('GCD=2,\\ LCM=24')) + dm('2\\times 24=48=6\\times 8')) + rvd(2, p('ដូច្នេះ បើដឹង GCD គេរក LCM បានភ្លាមៗ ។'))))
    S.append(prac(K6, 'លំហាត់គំរូ', p('គេរៀបសន្លឹកប័ណ្ណតូចៗរាងចតុកោណកែងមានបណ្តោយប្រវែង ' + m('12\\text{ cm}') + ' និងទទឹង ' + m('9\\text{ cm}') + ' តាមទិសដៅដូចគ្នាដើម្បីបង្កើតបានការ៉េមួយ ។ រកប្រវែងជ្រុងនៃការ៉េតូចបំផុតដែលគេអាចបង្កើតបាន ។') + fig(tiles_lcm(maxh='26vh'), '')))
    S.append(sol(K6, 'ដំណោះស្រាយ', cols(p('ប្រវែងជ្រុងការ៉េជាពហុគុណរួមនៃ ' + m('9') + ' និង ' + m('12') + ' ។ ដើម្បីឱ្យខ្លីបំផុត គេរក LCM ។') + dm('\\begin{aligned}9&=3^{2}\\\\ 12&=2^{2}\\times 3\\end{aligned}') + p(m('LCM(9,12)=2^{2}\\times 3^{2}=4\\times 9=36') + ' ។'), fig(tiles_lcm(maxh='34vh'))) + p('ដូចនេះការ៉េតូចបំផុតដែលអាចបង្កើតបានមានជ្រុងប្រវែង ' + hl(m('36\\text{ cm}'), RED) + ' (ប្រើសន្លឹកប័ណ្ណ ' + m('3\\times 4=12') + ' សន្លឹក) ។')))
    S.append(prac(K6, 'ប្រតិបត្តិ', p(m('x') + ' ជាចំនួនមួយមានលេខពីរខ្ទង់ ។ ' + m('58') + ' ចែកនឹង ' + m('x') + ' នៅសល់សំណល់ ' + m('2') + ' និង ' + m('73') + ' ចែកនឹង ' + m('x') + ' នៅសល់សំណល់ ' + m('3') + ' ហើយ ' + m('85') + ' ចែកនឹង ' + m('x') + ' នៅសល់សំណល់ ' + m('1') + ' ។ រកចំនួន ' + m('x') + ' នោះ ។')))
    S.append(sol(K6, 'ចម្លើយ', p('តាមលក្ខណៈនៃវិធីចែកមានសំណល់ ៖') + ul([m('58') + ' ចែកនឹង ' + m('x') + ' សល់ ' + m('2') + ' ' + m('\\Rightarrow 58-2=56') + ' ចែកដាច់នឹង ' + m('x'), m('73') + ' ចែកនឹង ' + m('x') + ' សល់ ' + m('3') + ' ' + m('\\Rightarrow 73-3=70') + ' ចែកដាច់នឹង ' + m('x'), m('85') + ' ចែកនឹង ' + m('x') + ' សល់ ' + m('1') + ' ' + m('\\Rightarrow 85-1=84') + ' ចែកដាច់នឹង ' + m('x')]) + p('ជាងនេះទៅទៀត តួចែក ' + m('x') + ' ត្រូវតែធំជាងសំណល់ទាំងអស់ គឺ ' + m('x>3') + ' ។ ដូច្នេះ ' + m('x') + ' ជាតួចែករួមនៃ ' + m('56, 70, 84') + ' ដែលមានពីរខ្ទង់ ។')))
    S.append(sol(K6, 'ចម្លើយ (បន្ត)', p('បំបែកចំនួនទាំងបីជាផលគុណកត្តាបឋម ៖') + dm('\\begin{aligned}56&=2^{3}\\times 7\\\\ 70&=2\\times 5\\times 7\\\\ 84&=2^{2}\\times 3\\times 7\\end{aligned}') + p(m('GCD(56,70,84)=2\\times 7=14') + ' ។ តួចែករួមគឺតួចែកនៃ ' + m('14') + ' ៖ ' + m('1, 2, 7, 14') + ' ។') + p('ដោយ ' + m('x') + ' ជាចំនួនមានលេខពីរខ្ទង់ ដូចនេះ ' + hl(m('x=14'), RED) + ' ។')))

    # ------------------------------------------------------------ 7  exercises (the book's 11 exercises)
    S.append({'k': 'title', 'html': '<h1>7. លំហាត់</h1><p class="ts-sub">១១ លំហាត់</p>'})
    book = json.load(open(os.path.join(os.path.dirname(__file__), 'book_exercises.json'), encoding='utf-8'))
    S.extend(book)

    # ------------------------------------------------------------ summary and the end
    sm = ('<table class="tbl sm"><tr><th>ប្រធានបទ</th><th>ចំណុចសំខាន់</th></tr>'
          '<tr><td>1. ចែកដាច់នឹង</td><td>2: ខ្ទង់រាយគូ · 5: ខ្ទង់រាយ 0/5 · 3,9: ផលបូកលេខ · 4: ពីរខ្ទង់ចុង · 8: បីខ្ទង់ចុង · 7: ' + m('a-2b') + '</td></tr>'
          '<tr><td>2. តួចែក / ពហុគុណ</td><td>' + m('18=2\\times 9') + ' · 2 ជាតួចែកនៃ 18 · 18 ជាពហុគុណនៃ 2</td></tr>'
          '<tr><td>3. ចំនួនបឋម</td><td>តួចែកតែពីរ (' + m('1') + ' និងខ្លួនឯង) · ' + m('2, 3, 5, 7, 11, 13, \\dots') + ' · ' + m('1') + ' មិនមែនបឋម</td></tr>'
          '<tr><td>4. កត្តាបឋម</td><td>' + m('60=2^{2}\\times 3\\times 5') + '</td></tr>'
          '<tr><td>5. GCD</td><td>កត្តារួម · និទស្សន្ត ' + hl('តូចជាងគេ', RED) + '</td></tr>'
          '<tr><td>6. LCM</td><td>កត្តារួម · និទស្សន្ត ' + hl('ធំជាងគេ', RED) + ' និងកត្តាមិនរួម</td></tr>'
          '<tr><td>ទំនាក់ទំនង</td><td>' + m('GCD\\times LCM=a\\times b') + '</td></tr></table>')
    S.append(key('សង្ខេបមេរៀនទី ២', 'សង្ខេប', sm))
    S.append({'k': 'title', 'html': '<p class="ts-kicker">មេរៀនទី ២</p><h1>ចប់មេរៀន</h1><p class="ts-sub">តួចែកនិងពហុគុណ</p><div class="th-you">សូមអរគុណ</div>'})
    return S
